<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Giriş | Eğitim Portalı</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>
body{min-height:100vh;margin:0;font-family:Inter,"Segoe UI",sans-serif;color:#252147;background:radial-gradient(circle at 10% 15%,#6d5dfc32,transparent 27%),radial-gradient(circle at 90% 80%,#18c8c632,transparent 25%),linear-gradient(145deg,#f5f3ff,#edf9ff)}.shell{min-height:100vh;display:grid;place-items:center;padding:1.25rem}.login{width:min(980px,100%);display:grid;grid-template-columns:.9fr 1.1fr;background:#fff;border:1px solid #ffffffaa;border-radius:32px;overflow:hidden;box-shadow:0 30px 90px #4939a32b}.form{padding:clamp(1.5rem,5vw,4rem)}.visual{padding:clamp(2rem,5vw,4rem);color:#fff;background:linear-gradient(145deg,#4338ca,#6d28d9 55%,#087ea4);position:relative;overflow:hidden}.orb{width:220px;height:220px;border-radius:50%;margin:2rem auto;border:26px solid #ffffff20;box-shadow:inset 0 0 0 18px #51e8df22,0 0 70px #58e7df55;display:grid;place-items:center}.orb i{font-size:4rem}.form-control,.input-group-text{padding:.8rem;border-color:#ddd9f3}.btn-login{border:0;color:#fff;font-weight:700;padding:.85rem;background:linear-gradient(120deg,#5b38db,#386fea,#0ba6a3);box-shadow:0 12px 30px #5939dc4d;transition:.2s}.btn-login:hover{color:#fff;transform:translateY(-2px);filter:saturate(1.2)}@media(max-width:780px){.login{grid-template-columns:1fr}.visual{min-height:260px}.orb{width:120px;height:120px;border-width:15px;margin:1rem auto}.orb i{font-size:2.5rem}}
